-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 17: Lambdas e fluxos Java SE 8 — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('5e272308-a525-59db-879d-c7072e316282', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Uma interface funcional possui:', '["Nenhum método.","Somente campos.","Um único método abstrato pertinente ao contrato.","Somente métodos static.","Exatamente dois construtores."]'::jsonb, 2, 'Métodos default e static não acrescentam outro método abstrato ao contrato funcional.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.2, páginas 608–610 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8e5d5489-827f-5aae-95ae-f5e3859611d0', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Uma expressão lambda pode fornecer:', '["Uma nova classe-fonte pública obrigatória.","Uma implementação do contrato de interface funcional.","Um construtor de interface.","Uma variável global sem tipo.","Um pacote."]'::jsonb, 1, 'A tipagem depende da interface funcional alvo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.2, páginas 608–610 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b1fd648b-abd6-5ee9-9f82-68246fde4583', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', '@FunctionalInterface auxilia a:', '["Executar a lambda automaticamente.","Criar uma thread sempre.","Verificar que o tipo atende ao contrato de interface funcional.","Tornar todos os métodos static.","Desativar a verificação de tipos."]'::jsonb, 2, 'A anotação expressa uma intenção validada pelo compilador.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.2, páginas 608–610 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0d38e45e-e6e0-5ded-8089-50ff19e952db', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Difícil', 'Uma variável local capturada por lambda Java SE 8 deve ser:', '["Volatile obrigatoriamente.","Reatribuída após cada captura.","Sempre public.","Final ou efetivamente final.","Sempre static."]'::jsonb, 3, 'Efetivamente final significa não ser reatribuída após sua inicialização pertinente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.2, páginas 608–610 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4e3b0b2c-7739-584a-81f5-98b7fe06a3c8', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'Filter em um stream produz principalmente:', '["Uma thread por elemento.","Um fluxo com elementos que satisfazem o predicado.","Uma ordenação automática.","Um valor único sempre.","Uma alteração obrigatória da coleção fonte."]'::jsonb, 1, 'Filter é uma operação intermediária de seleção.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('42fb67f4-6bc2-5045-ae33-7c01165cd071', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Map em um stream faz principalmente:', '["Transformar elementos por uma função.","Confirmar arquivos.","Ordenar chaves.","Remover toda duplicata.","Criar obrigatoriamente um java.util.Map."]'::jsonb, 0, 'Map de stream e a interface Map são conceitos diferentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('162cad90-f18a-53ed-8eac-f902c480c860', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Qual operação é terminal em IntStream?', '["sorted().","filter().","map().","sum().","limit()."]'::jsonb, 3, 'A operação terminal consome o pipeline para produzir resultado ou efeito.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ff4d98c8-20b8-5dcb-9c19-a1fcbfb06d1d', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Difícil', 'Operações intermediárias de stream são normalmente:', '["Preguiçosas, realizadas quando há consumo terminal pertinente.","Executadas integralmente ao serem declaradas sempre.","Proibidas em fluxos vazios.","Sempre paralelas.","Sempre destrutivas para a fonte."]'::jsonb, 0, 'A avaliação pode evitar trabalho desnecessário conforme o pipeline.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bfe89025-40cc-5c88-9795-cc29a8da5bde', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Qual resultado de `IntStream.of(2,3,4).filter(x->x%2==0).sum()`?', '["4.","6.","2.","9.","0."]'::jsonb, 1, 'A seleção retém 2 e 4 antes da soma.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c1306739-e315-5fac-9f90-c394b1e68413', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Qual resultado de `IntStream.of(1,2,3).map(x->x*2).sum()`?', '["0.","6.","12.","9.","3."]'::jsonb, 2, 'A transformação produz 2, 4 e 6.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f3d8bdee-e13a-5276-b4ba-d0af9b10c1a3', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Qual resultado de `IntStream.of(1,2,2,3).distinct().count()`?', '["2.","6.","3.","1.","4."]'::jsonb, 2, 'Distinct remove repetições antes da contagem.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9d64a4a8-a194-5e5c-ba95-e9348e3c217d', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Difícil', 'Um stream já consumido por uma operação terminal pode ser reutilizado normalmente?', '["Somente se contiver inteiros.","Sim, reinicia automaticamente.","Sim, com o mesmo forEach.","Somente se ordenado.","Não; deve-se obter outro stream."]'::jsonb, 4, 'Streams não são coleções reutilizáveis de resultados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2cf9f5f8-2260-5157-9b6f-eec136531c43', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Stream<Integer> difere de IntStream porque:', '["O primeiro trabalha com objetos Integer; o segundo com especialização primitiva int.","O primeiro é sempre paralelo.","O segundo só aceita valores positivos.","O primeiro não admite filter.","Ambos são exatamente o mesmo tipo."]'::jsonb, 0, 'Especializações primitivas oferecem operações próprias e evitam empacotamento em certos usos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.4, páginas 617–618 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0075e6b1-f3cb-5587-b8f4-bdd4b3a2cf44', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Uma referência de método como `String::toUpperCase` pode:', '["Executar imediatamente em todas as strings da JVM.","Criar uma thread obrigatória.","Retornar sempre um Class.","Substituir qualquer construtor.","Representar comportamento compatível com uma interface funcional alvo."]'::jsonb, 4, 'O significado e a compatibilidade dependem do contexto de tipagem.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.5, páginas 619 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('da8cb41c-6627-5113-8643-b0470b83d130', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Collectors.toList é empregado normalmente para:', '["Eliminar duplicatas necessariamente.","Criar apenas listas imutáveis.","Ordenar sempre a lista.","Escrever arquivos automaticamente.","Reunir elementos de um stream em uma lista."]'::jsonb, 4, 'O coletor não promete por si só todas essas propriedades adicionais.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.6, páginas 620–626 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fa55700d-8aac-5ad2-b9c9-cfb4714f32a8', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'GroupingBy permite principalmente:', '["Criar uma interface.","Executar uma transação.","Ordenar os pacotes.","Agrupar elementos por uma chave calculada.","Modificar diretamente todos os objetos."]'::jsonb, 3, 'Um classificador define a chave de cada grupo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.6, páginas 620–626 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1ec49f92-2343-5405-8a4e-60b981c13e71', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Um stream obtido de linhas de arquivo exige atenção ao:', '["Número de construtores.","Conteúdo do classpath exclusivamente.","Nome do método main apenas.","Tipo de uma janela.","Fechamento do recurso de leitura."]'::jsonb, 4, 'Try-with-resources pode controlar a vida útil do recurso correspondente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.7, páginas 627–628 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('09a1b325-f764-5d4b-bcd9-a4ea9a50f408', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Limit(n) sobre um fluxo de valores aleatórios serve para:', '["Fixar todos em zero.","Ordenar os números.","Garantir ausência de repetição.","Restringir a quantidade de elementos consumidos naquele resultado.","Criptografar os valores."]'::jsonb, 3, 'Fluxos potencialmente ilimitados precisam de limites adequados em certas operações.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.8, páginas 629–630 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ac4e4b75-8023-5466-abe2-8be902f023ff', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Uma lambda pode tratar um ActionEvent porque ActionListener é:', '["Um tipo primitivo.","Uma interface funcional.","Um pacote.","Um array.","Uma classe final."]'::jsonb, 1, 'O método abstrato actionPerformed fornece o contrato alvo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.9, páginas 631 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0c973830-449d-536d-aefc-52c2ff7a60e2', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Difícil', 'Um reduce com identidade 0 e soma em inteiros calcula:', '["Uma acumulação por adição.","Uma ordenação.","Uma conexão de rede.","O maior elemento obrigatoriamente.","Um Set sempre."]'::jsonb, 0, 'A identidade deve ser compatível com o operador de redução.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 17, seção 17.3, páginas 611–616 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
